-- Round 11 (chat, 4 Oct 2026): body edits on 7 reviews (15 edits): piece counts, duplicate or
-- contradictory verdict lines, old MRP figures. Each review gets one dated correction note.
UPDATE public.reviews SET content = replace(content, '₹40,319 at Toycra, ₹10,080 under MRP. Verdict: BUY.', '₹40,319 at Toycra, ₹10,080 under MRP.') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review repeated its verdict line, and the extra line has been removed.*' WHERE slug = 'lego-10316-rivendell-review' AND position('₹40,319 at Toycra, ₹10,080 under MRP. Verdict: BUY.' in content) > 0;
UPDATE public.reviews SET content = replace(replace(replace(content, 'packs in 740 pieces', 'packs in 747 pieces'), 'At an official Indian MRP of ₹5,400,', 'At an official Indian MRP of ₹5,999,'), 'At ₹5,400 (MRP),', 'At ₹5,999 (MRP),') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review gave the wrong piece count and an old figure as LEGO''s Indian MRP. Both are now fixed.*' WHERE slug = 'lego-77264-jaguar-f-type-project-7-land-rover-defender-class' AND position('packs in 740 pieces' in content) > 0 AND position('At an official Indian MRP of ₹5,400,' in content) > 0 AND position('At ₹5,400 (MRP),' in content) > 0;
UPDATE public.reviews SET content = replace(replace(replace(content, 'At 5,201 pieces', 'At 5,202 pieces'), 'this is probably a BUY NOW.', 'this is probably worth it.'), '' || chr(10) || '' || chr(10) || 'Verdict: WAIT. Good set, but the price will drop.', '') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review gave the wrong piece count and included a second verdict line that contradicted it. Both are now fixed.*' WHERE slug = 'lego-avengers-tower-76269-worth-39199' AND position('At 5,201 pieces' in content) > 0 AND position('this is probably a BUY NOW.' in content) > 0 AND position('' || chr(10) || '' || chr(10) || 'Verdict: WAIT. Good set, but the price will drop.' in content) > 0;
UPDATE public.reviews SET content = replace(replace(replace(content, 'At ₹2,900, this isn', 'At ₹2,999, this isn'), 'has an official MRP of ₹2,900', 'has an official MRP of ₹2,999'), 'For ₹2,900, you', 'For ₹2,999, you') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review gave an old figure as LEGO''s Indian MRP, which now shows the current MRP.*' WHERE slug = 'lego-bmw-m3-e30-77263-worth-2900' AND position('At ₹2,900, this isn' in content) > 0 AND position('has an official MRP of ₹2,900' in content) > 0 AND position('For ₹2,900, you' in content) > 0;
UPDATE public.reviews SET content = replace(replace(content, '' || chr(10) || '' || chr(10) || 'BUY NOW' || chr(10) || 'On that bombshell', '' || chr(10) || '' || chr(10) || 'On that bombshell'), '' || chr(10) || '' || chr(10) || 'Verdict: WAIT. Good set, but the price will drop.', '') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review had a second verdict line that contradicted the verdict, and that line has been removed.*' WHERE slug = 'lego-city-police-train-heist-60508-19999-for-a-cat-and-mouse' AND position('' || chr(10) || '' || chr(10) || 'BUY NOW' || chr(10) || 'On that bombshell' in content) > 0 AND position('' || chr(10) || '' || chr(10) || 'Verdict: WAIT. Good set, but the price will drop.' in content) > 0;
UPDATE public.reviews SET content = replace(content, '' || chr(10) || '' || chr(10) || 'BUY NOW' || chr(10) || 'On that bombshell', '' || chr(10) || '' || chr(10) || 'On that bombshell') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review repeated its verdict line, and the extra line has been removed.*' WHERE slug = 'lego-creative-flower-shop-42693-worth-2999' AND position('' || chr(10) || '' || chr(10) || 'BUY NOW' || chr(10) || 'On that bombshell' in content) > 0;
UPDATE public.reviews SET content = replace(replace(content, 'It’s a BUY NOW if you have the disposable income', 'It’s worth it if you have the disposable income'), 'Bubyee.' || chr(10) || '' || chr(10) || 'Verdict: WAIT.' || chr(10) || '', 'Bubyee.' || chr(10) || '') || '' || chr(10) || '' || chr(10) || '*Correction (4 October 2026): an earlier version of this review had a second verdict line that contradicted the verdict, and that line has been removed.*' WHERE slug = 'lego-dungeons-dragons-red-dragons-tale-21348-worth-35999' AND position('It’s a BUY NOW if you have the disposable income' in content) > 0 AND position('Bubyee.' || chr(10) || '' || chr(10) || 'Verdict: WAIT.' || chr(10) || '' in content) > 0;
